        const italicEl = this._getInlineFormatAtNode(target, 'italic');
        const underEl  = this._getInlineFormatAtNode(target, 'underline');
        const strikeEl = this._getInlineFormatAtNode(target, 'line-through');
        const codeEl   = this._getInlineFormatAtNode(target, 'code');
        if (boldEl)   items.push({ label: 'Remove Bold',          icon: 'Delete', action: () => { this.content.focus({ preventScroll: true }); this.bold(); } });
        if (italicEl) items.push({ label: 'Remove Italic',        icon: 'Delete', action: () => { this.content.focus({ preventScroll: true }); this.italic(); } });
        if (underEl)  items.push({ label: 'Remove Underline',     icon: 'Delete', action: () => { this.content.focus({ preventScroll: true }); this.underline(); } });
        if (strikeEl) items.push({ label: 'Remove Strikethrough', icon: 'Delete', action: () => { this.content.focus({ preventScroll: true }); this.strikethrough(); } });
        if (codeEl)   items.push({ label: 'Remove Inline Code',   icon: 'Delete', action: () => { this.content.focus({ preventScroll: true }); this.inlinecode(); } });
        if (items.length > 0) items.push({ divider: true });
