    _genericDialog(dialogId, title, insertMethod, bodyHTML, footerLeftHTML = '', headerRightHTML = '') {
        const id = this._uid;
        const footerStyle = footerLeftHTML
            ? 'display:flex;justify-content:space-between;align-items:center;'
            : 'text-align:right;';
        const uploadImageTabAttrs = dialogId === 'rich-text-box-upload-image-modal'
            ? { close: ' tabindex="10"', footerClose: ' tabindex="8"', ok: ' tabindex="9"' }
            : { close: '', footerClose: '', ok: '' };
        const closeButtonHTML = `<button class="rich-text-box-modal-close" aria-label="Close dialog"${uploadImageTabAttrs.close} onclick="RTNative_Method('closeDialog','${id}','${dialogId}')"><svg viewBox="0 0 12 12" aria-hidden="true" focusable="false" width="8" height="8" style="display:block"><path d="M2 2L10 10M10 2L2 10" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" fill="none"/></svg></button>`;
        return `
<dialog id="${dialogId}" class="rich-text-box-modal rtb-centered-dialog" aria-modal="true" aria-labelledby="${dialogId}-title">
  <div class="rtb-modal-header">
    <div id="${dialogId}-title" class="rich-text-box-modal-title">${title}</div>
    ${headerRightHTML ? `<div style="display:flex;gap:2px;align-items:center;">${headerRightHTML}${closeButtonHTML}</div>` : closeButtonHTML}
  </div>
  <div class="rtb-modal-scroll-area rich-text-box-scroll">
    <div class="rtb-modal-body">
      ${bodyHTML}
    </div>
    <div class="rtb-modal-footer" style="${footerStyle}">
      ${footerLeftHTML ? `<div>${footerLeftHTML}</div>` : ''}
      <div>
        <button class="rich-text-box-form-button"${uploadImageTabAttrs.footerClose} onclick="RTNative_Method('closeDialog','${id}','${dialogId}')">Close</button>
        <button id="rich-text-box-ok-button" class="rich-text-box-form-button"${uploadImageTabAttrs.ok} onclick="RTNative_Method('${insertMethod}','${id}')">OK</button>
      </div>
    </div>
  </div>
</dialog>`;
    }

